<?php require_once '../config.php'; require_customer(); $u=current_customer();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); if(isset($_POST['redeem_reward'])) { $rid=(int)($_POST['reward_id']??0); try { db()->beginTransaction(); $lock=db()->prepare('SELECT points FROM customers WHERE id=? FOR UPDATE'); $lock->execute([$u['id']]); $balance=(int)$lock->fetchColumn(); $rw=db()->prepare('SELECT id,name,points_required FROM rewards WHERE id=? AND active=1 FOR UPDATE'); $rw->execute([$rid]); $reward=$rw->fetch(); if(!$reward || $balance < (int)$reward['points_required']) { db()->rollBack(); flash('Not enough points or this reward is unavailable.','error'); } else { db()->prepare('UPDATE customers SET points=points-? WHERE id=?')->execute([$reward['points_required'],$u['id']]); db()->prepare("INSERT INTO reward_redemptions(customer_id,reward_id,points_spent,status) VALUES(?,?,?,'pending')")->execute([$u['id'],$rid,$reward['points_required']]); db()->prepare('INSERT INTO points_ledger(customer_id,points,entry_type,description) VALUES(?,?,?,?)')->execute([$u['id'],-$reward['points_required'],'spent','Redeemed reward: '.$reward['name']]); db()->commit(); flash('Reward redemption requested. The factory team will contact you.'); } } catch(Throwable $e) { if(db()->inTransaction()) db()->rollBack(); flash('Could not redeem this reward. Please try again.','error'); } redirect('dashboard.php'); } $code=strtoupper(trim($_POST['code']??''));$ip=$_SERVER['REMOTE_ADDR']??'unknown';
 $q=db()->prepare('SELECT COUNT(*) FROM redemption_attempts WHERE customer_id=? AND attempted_at >= DATE_SUB(NOW(), INTERVAL 1 HOUR)');$q->execute([$u['id']]);
 if((int)$q->fetchColumn()>=MAX_CODE_ATTEMPTS_PER_HOUR){flash('Too many attempts. Please try again after an hour.','error');redirect('dashboard.php');}
 db()->prepare('INSERT INTO redemption_attempts(customer_id,ip_address) VALUES(?,?)')->execute([$u['id'],$ip]);
 if(!preg_match('/^[A-Z0-9]{12}$/',$code)){flash('Code format is invalid. Check the 12-character code inside your box.','error');redirect('dashboard.php');}
 try{db()->beginTransaction();$s=db()->prepare('SELECT id,status FROM product_codes WHERE code=? FOR UPDATE');$s->execute([$code]);$c=$s->fetch();if(!$c||$c['status']!=='active'){db()->rollBack();flash('This code is invalid or has already been used.','error');redirect('dashboard.php');}
 $up=db()->prepare("UPDATE product_codes SET status='redeemed',customer_id=?,redeemed_at=NOW() WHERE id=? AND status='active'");$up->execute([$u['id'],$c['id']]);if($up->rowCount()!==1){db()->rollBack();flash('This code has already been redeemed.','error');redirect('dashboard.php');}
 db()->prepare('UPDATE customers SET points=points+? WHERE id=?')->execute([POINTS_PER_CODE,$u['id']]);db()->prepare('INSERT INTO points_ledger(customer_id,points,entry_type,description,reference_code_id) VALUES(?,?,?,?,?)')->execute([$u['id'],POINTS_PER_CODE,'earned','Product code redeemed',$c['id']]);db()->commit();flash('Success! '.POINTS_PER_CODE.' points added to your account.');
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('We could not process that code. Please try again.','error');} redirect('dashboard.php');
}
$history=db()->prepare('SELECT points,entry_type,description,created_at FROM points_ledger WHERE customer_id=? ORDER BY id DESC LIMIT 20');$history->execute([$u['id']]);$rows=$history->fetchAll();$rewards=db()->query('SELECT * FROM rewards WHERE active=1 ORDER BY points_required')->fetchAll();
page_start('My rewards'); ?>
<div class="stats"><div class="stat"><span>Available points</span><strong><?=number_format($u['points'])?></strong></div><div class="stat"><span>Member since</span><strong><?=e(date('M Y',strtotime($u['created_at'])))?></strong></div></div>
<div class="grid two"><section class="panel"><h2>Redeem a box code</h2><p>Enter the 12-character code printed inside your product box.</p><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Product code<input name="code" maxlength="12" minlength="12" pattern="[A-Za-z0-9]{12}" placeholder="AB12CD34EF56" required></label><button class="btn">Verify code & earn points</button></form><small>Each valid code can be used once. <?=POINTS_PER_CODE?> points per code.</small></section><section class="panel"><h2>Available rewards</h2><?php if(!$rewards):?><p>No rewards are available yet.</p><?php else: foreach($rewards as $r):?><div class="reward"><div><b><?=e($r['name'])?></b><p><?=e($r['description'])?></p></div><div><strong><?=number_format($r['points_required'])?> pts</strong><?php if((int)$u['points'] >= (int)$r['points_required']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="reward_id" value="<?=e($r['id'])?>"><button class="btn small" name="redeem_reward" value="1">Redeem</button></form><?php endif;?></div></div><?php endforeach;endif;?></section></div>
<section class="panel"><h2>Points history</h2><div class="table-wrap"><table><tr><th>Date</th><th>Activity</th><th>Type</th><th>Points</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['description'])?></td><td><?=e(ucfirst($r['entry_type']))?></td><td class="<?=((int)$r['points']>=0?'positive':'negative')?>"><?=((int)$r['points']>0?'+':'')?><?=e($r['points'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">No activity yet. Redeem your first code!</td></tr><?php endif;?></table></div></section>
<?php page_end(); ?>
